import React from 'react';
import './index.css';

const AppSimple: React.FC = () => {
  return (
    <div className="min-h-screen bg-dark-primary text-dark-text">
      <div className="p-8">
        <h1 className="text-3xl font-bold text-white mb-4">Test App</h1>
        <p className="text-white">If you can see this, the basic React setup is working.</p>
        <button className="px-4 py-2 bg-blue-600 text-white rounded mt-4">
          Test Button
        </button>
      </div>
    </div>
  );
};

export default AppSimple;
